              "model_answers": {
                "B1": "I want to learn a new language because I love traveling. It helps me talk to local people and understand their culture better.",
                "B2": "Learning a new language is essential for my career growth. Additionally, I am passionate about traveling and immersing myself in different cultures."
              },
              "word_count_check": "Mẫu B1 có 24 từ. Mẫu B2 có 23 từ. Cả hai đều nằm trong khoảng 20-30 từ.",
              "explanation": "Part 2 yêu cầu viết thành câu hoàn chỉnh nhưng phải ngắn gọn (20-30 từ). Tránh viết quá ngắn (dưới 20 từ) sẽ bị trừ điểm, và quá dài sẽ tốn thời gian. Dùng từ nối như 'because', 'Additionally' để ghép ý."
