                "B1": "In this picture, I can see an office. There are many people. They are sitting at their desks and working on computers. One man is pointing at a screen. Maybe they are discussing a project. The office looks busy.",
                "B2": "This image shows a typical modern office environment. There are several colleagues focused on their computer screens. In the foreground, one man is pointing at a monitor, so I guess they are collaborating on a specific project. Overall, the atmosphere seems quite busy and productive."
