          "subskill_id": "W3",
          "name": "Chat Voice Training",
          "description": "Viết 3 responses (~40 từ mỗi cái) cho social media chat — giọng friendly, on-topic",
          "target_task": "Writing Part 3",
          "exercises": [
            {
              "id": 1,
              "type": "short_writing",
              "prompt": "You are in a social media chat room about travel. Respond to the member. Write about 30-40 words.",
              "message": "Sam: Hi! I'm planning my first solo trip to a foreign country and I'm a bit nervous. Have you ever traveled alone? How was it?",
              "model_answers": {
                "B1": "Hi Sam! Yes, I traveled to Japan alone last year. It was scary at first, but I met many friendly people. You should definitely try it, just plan your trip carefully.",
                "B2": "Hi Sam! Traveling alone is completely normal to be nervous about. I did a solo trip to Italy recently and it was an eye-opening experience. It really builds your confidence. Just make sure to research your destination well beforehand!"
              },
              "word_count_check": "B1: 32 từ. B2: 39 từ.",
              "explanation": "Trong Part 3, ngôn ngữ cần thân thiện, giống như chat trên mạng xã hội (dùng 'Hi Sam!', dấu !). Phải trả lời trực tiếp 2 câu hỏi của Sam: Đã từng đi chưa? và Cảm giác thế nào? B2 dùng từ vựng tốt hơn ('eye-opening experience', 'builds your confidence')."
            },
            {
              "id": 2,
              "type": "short_answer",
              "prompt": "Tình huống: Bạn vừa tham gia CLB Sách. Viết một tin nhắn ngắn (20-30 từ) trong nhóm chat giới thiệu về bản thân và loại sách bạn thích đọc (Informal style).",
              "model_answers": {
                "Gợi ý (B1/B2)": "Hi everyone! I'm John. I just joined the club today. I absolutely love reading science fiction and fantasy novels. Can't wait to discuss books with you all!"
              },
              "explanation": "Sử dụng giọng điệu thân mật (Hi everyone, Can't wait), viết ngắn gọn nhưng đầy đủ ý theo yêu cầu."
            },
            {
              "id": 3,
              "type": "short_answer",
              "prompt": "Tình huống: CLB Thể thao của bạn bị hủy lịch tập chiều nay do mưa lớn. Trả lời tin nhắn của một thành viên khác đang phàn nàn về việc này (30-40 từ, Informal style).",
              "model_answers": {
                "Gợi ý (B1/B2)": "Yeah, it's such a bummer! I was really looking forward to playing football today. But I guess we can't do much about the weather. Let's hope it clears up so we can practice tomorrow instead."
              },
              "explanation": "Dùng ngôn ngữ tự nhiên, đời thường (Yeah, it's such a bummer, looking forward to, I guess) để phù hợp với ngữ cảnh chat nhóm."
            }
          ]
