              "type": "multiple_choice",
              "prompt": "Nghe hiểu thái độ/quan điểm (Opinion Attribution).",
              "transcript": "[Man]: I honestly don't think voting changes anything. The politicians just make promises they can't keep.\n[Woman]: I completely disagree. If you don't vote, you lose your right to complain about the policies they implement.\n[PAUSE]",
              "text_only_version": "Man: I honestly don't think voting changes anything. The politicians just make promises they can't keep.\nWoman: I completely disagree. If you don't vote, you lose your right to complain about the policies they implement.",
